from social_graph.types import NodeID, Edge, User
from social_graph.graph import SocialGraph


class ShardingStrategy:
    def __init__(self, num_shards: int = 8) -> None:
        self._num_shards = num_shards

    @property
    def num_shards(self) -> int:
        return self._num_shards

    def shard_for(self, node_id: NodeID) -> int:
        return abs(hash(node_id)) % self._num_shards

    def shards_for_edge(self, u: NodeID, v: NodeID) -> Tuple[int, int]:
        return self.shard_for(u), self.shard_for(v)


class Shard:
    def __init__(self, shard_id: int) -> None:
        self.shard_id = shard_id
        self._graph = SocialGraph()

    def add_node(self, node_id: NodeID, user: Optional[User] = None) -> None:
        self._graph.add_node(user=user, node_id=node_id)

    def add_edge(self, u: NodeID, v: NodeID) -> None:
        self._graph.add_edge(u, v)

    def get_neighbors(self, node_id: NodeID) -> List[NodeID]:
        return self._graph.get_neighbors(node_id)

    @property
    def node_count(self) -> int:
        return self._graph.node_count

    @property
    def edge_count(self) -> int:
        return self._graph.edge_count

    def has_node(self, node_id: NodeID) -> bool:
        return self._graph.has_node(node_id)


class ShardedGraph:
    def __init__(self, num_shards: int = 8, directed: bool = False) -> None:
        self._strategy = ShardingStrategy(num_shards)
        self._shards: List[Shard] = [Shard(i) for i in range(num_shards)]
        self._directed = directed
        self._node_count = 0
        self._edge_count = 0
        self._node_shard_map: Dict[NodeID, int] = {}

    @property
    def num_shards(self) -> int:
        return self._strategy.num_shards

    @property
    def node_count(self) -> int:
        return self._node_count

    @property
    def edge_count(self) -> int:
        return self._edge_count

    def add_node(self, user: Optional[User] = None, node_id: Optional[NodeID] = None) -> NodeID:
        if user is not None:
            nid = user.user_id
        elif node_id is not None:
            nid = node_id
            user = User(user_id=nid)
        else:
            raise ValueError("Either user or node_id must be provided")

        s = self._strategy.shard_for(nid)
        self._shards[s].add_node(nid, user)
        self._node_shard_map[nid] = s
        self._node_count += 1
        return nid

    def add_edge(self, u: NodeID, v: NodeID) -> None:
        if u == v:
            return
        s_u, s_v = self._strategy.shards_for_edge(u, v)
        if u not in self._node_shard_map:
            self.add_node(node_id=u)
        if v not in self._node_shard_map:
            self.add_node(node_id=v)
        self._shards[s_u].add_edge(u, v)
        if not self._directed:
            self._shards[s_v].add_edge(u, v)
        self._edge_count += 1

    def get_neighbors(self, node_id: NodeID) -> List[NodeID]:
        if node_id not in self._node_shard_map:
            return []
        s = self._node_shard_map[node_id]
        return self._shards[s].get_neighbors(node_id)

    def shard_for(self, node_id: NodeID) -> int:
        return self._strategy.shard_for(node_id)

    def has_node(self, node_id: NodeID) -> bool:
        return node_id in self._node_shard_map

    @property
    def nodes(self) -> List[NodeID]:
        return list(self._node_shard_map.keys())

    def edges(self) -> List[Edge]:
        seen: Set[Tuple[int, int]] = set()
        result = []
        for nid in self._node_shard_map:
            s = self._node_shard_map[nid]
            for nb in self._shards[s].get_neighbors(nid):
                key = (min(nid, nb), max(nid, nb)) if not self._directed else (nid, nb)
                if key not in seen:
                    seen.add(key)
                    result.append((nid, nb))
        return result

from __future__ import annotations

from collections import OrderedDict
from typing import Any, Dict, Iterator, Optional


class LRUCache:
    def __init__(self, capacity: int = 1024) -> None:
        self._capacity = max(1, capacity)
        self._store: OrderedDict = OrderedDict()
        self._hits: int = 0
        self._misses: int = 0

    def get(self, key: Any, default: Any = None) -> Any:
        if key in self._store:
            self._store.move_to_end(key)
            self._hits += 1
            return self._store[key]
        self._misses += 1
        return default

    def put(self, key: Any, value: Any) -> None:
        if key in self._store:
            self._store.move_to_end(key)
        self._store[key] = value
        if len(self._store) > self._capacity:
            self._store.popitem(last=False)

    def remove(self, key: Any) -> None:
        self._store.pop(key, None)

    def clear(self) -> None:
        self._store.clear()
        self._hits = 0
        self._misses = 0

    def __contains__(self, key: Any) -> bool:
        return key in self._store

    def __len__(self) -> int:
        return len(self._store)

    def __iter__(self) -> Iterator:
        return iter(self._store)

    @property
    def capacity(self) -> int:
        return self._capacity

    @property
    def hits(self) -> int:
        return self._hits

    @property
    def misses(self) -> int:
        return self._misses

    @property
    def hit_rate(self) -> float:
        total = self._hits + self._misses
        return self._hits / total if total > 0 else 0.0


class CacheLayer:
    def __init__(self, graph: Any, cache: Optional[LRUCache] = None, capacity: int = 1024) -> None:
        self._graph = graph
        self._cache = cache if cache is not None else LRUCache(capacity)

    def get_neighbors(self, node_id: int) -> list[int]:
        cached = self._cache.get(node_id)
        if cached is not None:
            return cached
        neighbors = self._graph.get_neighbors(node_id)
        self._cache.put(node_id, neighbors)
        return neighbors

    def invalidate(self, node_id: int) -> None:
        self._cache.remove(node_id)

    def warm(self, node_ids: list[int]) -> None:
        for nid in node_ids:
            if nid not in self._cache:
                self._cache.put(nid, self._graph.get_neighbors(nid))

    @property
    def cache(self) -> LRUCache:
        return self._cache

    def clear(self) -> None:
        self._cache.clear()

from __future__ import annotations

import heapq
from collections import defaultdict, deque
from typing import Dict, Iterator, List, Optional, Set, Tuple, Union

from social_graph.types import NodeID, Edge
from social_graph.graph import SocialGraph
from social_graph.shard import ShardedGraph


GraphLike = Union[SocialGraph, ShardedGraph]


class QueryEngine:
    def __init__(self, graph: GraphLike) -> None:
        self._graph = graph

    def friends_of_friends(self, node_id: NodeID) -> Set[NodeID]:
        direct = set(self._graph.get_neighbors(node_id))
        result: Set[NodeID] = set()
        for friend in direct:
            for fof in self._graph.get_neighbors(friend):
                if fof != node_id and fof not in direct:
                    result.add(fof)
        return result

    def mutual_friends(self, a: NodeID, b: NodeID) -> Set[NodeID]:
        neigh_a = set(self._graph.get_neighbors(a))
        neigh_b = set(self._graph.get_neighbors(b))
        return neigh_a & neigh_b

    def are_connected(self, a: NodeID, b: NodeID) -> bool:
        return b in set(self._graph.get_neighbors(a))

    def shortest_path(self, start: NodeID, end: NodeID) -> List[NodeID]:
        if start == end:
            return [start]
        if start not in self._graph or end not in self._graph:
            return []

        f_visited: Dict[NodeID, Optional[NodeID]] = {start: None}
        b_visited: Dict[NodeID, Optional[NodeID]] = {end: None}
        f_queue = deque([start])
        b_queue = deque([end])
        f_dist: Dict[NodeID, int] = {start: 0}
        b_dist: Dict[NodeID, int] = {end: 0}
        meeting_node: Optional[NodeID] = None

        while f_queue and b_queue:
            for queue, visited, other_visited, dist, other_dist in [
                (f_queue, f_visited, b_visited, f_dist, b_dist),
                (b_queue, b_visited, f_visited, b_dist, f_dist),
            ]:
                if not queue:
                    continue
                current = queue.popleft()
                if current in other_visited:
                    meeting_node = current
                    break

                for neighbor in self._graph.get_neighbors(current):
                    if neighbor not in visited:
                        visited[neighbor] = current
                        dist[neighbor] = dist[current] + 1
                        queue.append(neighbor)
                        if neighbor in other_visited:
                            meeting_node = neighbor
                            break
                if meeting_node is not None:
                    break
            if meeting_node is not None:
                break

        if meeting_node is None:
            return []

        path: List[NodeID] = []
        node: Optional[NodeID] = meeting_node
        while node is not None:
            path.append(node)
            node = f_visited.get(node)
        path.reverse()

        node = b_visited.get(meeting_node)
        while node is not None:
            path.append(node)
            node = b_visited.get(node)

        return path

    def shortest_path_length(self, start: NodeID, end: NodeID) -> int:
        path = self.shortest_path(start, end)
        if not path:
            return -1
        return len(path) - 1

    def suggest_friends(self, node_id: NodeID, limit: int = 10) -> List[Tuple[NodeID, int]]:
        direct = set(self._graph.get_neighbors(node_id))
        scores: Dict[NodeID, int] = defaultdict(int)

        for friend in direct:
            for fof in self._graph.get_neighbors(friend):
                if fof != node_id and fof not in direct:
                    scores[fof] += 1

        heap: List[Tuple[int, NodeID]] = []
        for candidate, count in scores.items():
            if len(heap) < limit:
                heapq.heappush(heap, (count, candidate))
            elif count > heap[0][0]:
                heapq.heapreplace(heap, (count, candidate))

        result = [(candidate, count) for count, candidate in sorted(heap, reverse=True, key=lambda x: (-x[0], x[1]))]
        return result

    def degree_centrality(self) -> Dict[NodeID, float]:
        if self._graph.node_count == 0:
            return {}
        n = self._graph.node_count - 1
        if n == 0:
            return {node: 0.0 for node in self._graph.nodes}
        return {node: self._graph.get_degree(node) / n for node in self._graph.nodes}

    def common_neighbors(self, a: NodeID, b: NodeID) -> int:
        return len(self.mutual_friends(a, b))

    def jaccard_similarity(self, a: NodeID, b: NodeID) -> float:
        neigh_a = set(self._graph.get_neighbors(a))
        neigh_b = set(self._graph.get_neighbors(b))
        union = neigh_a | neigh_b
        intersection = neigh_a & neigh_b
        if not union:
            return 0.0
        return len(intersection) / len(union)

from __future__ import annotations

from collections import defaultdict
from typing import Dict, Iterator, List, Optional, Set, Tuple, Union

from social_graph.types import NodeID
from social_graph.graph import SocialGraph
from social_graph.shard import ShardedGraph
from social_graph.union_find import UnionFind

GraphLike = Union[SocialGraph, ShardedGraph]


class CommunityDetector:
    def __init__(self, graph: GraphLike) -> None:
        self._graph = graph

    def connected_components(self) -> Dict[int, List[NodeID]]:
        uf = UnionFind()
        for node in self._graph.nodes:
            uf.make_set(node)
        for node in self._graph.nodes:
            for neighbor in self._graph.get_neighbors(node):
                uf.union(node, neighbor)
        return uf.components()

    def label_propagation(self, max_iterations: int = 50) -> Dict[NodeID, int]:
        labels: Dict[NodeID, int] = {}
        for i, node in enumerate(self._graph.nodes):
            labels[node] = node

        import random
        rng = random.Random(42)

        for iteration in range(max_iterations):
            changed = False
            nodes = list(self._graph.nodes)
            rng.shuffle(nodes)

            for node in nodes:
                if not self._graph.get_neighbors(node):
                    continue

                label_counts: Dict[int, int] = defaultdict(int)
                for neighbor in self._graph.get_neighbors(node):
                    label_counts[labels[neighbor]] += 1

                if not label_counts:
                    continue

                max_count = max(label_counts.values())
                best_labels = [l for l, c in label_counts.items() if c == max_count]
                best_label = best_labels[0]

                if labels[node] != best_label:
                    labels[node] = best_label
                    changed = True

            if not changed:
                break

        label_map: Dict[int, int] = {}
        next_id = 0
        remapped: Dict[NodeID, int] = {}
        for node in self._graph.nodes:
            raw = labels[node]
            if raw not in label_map:
                label_map[raw] = next_id
                next_id += 1
            remapped[node] = label_map[raw]

        return remapped

    def communities(self, method: str = "connected_components") -> Dict[int, List[NodeID]]:
        if method == "connected_components":
            return self.connected_components()
        elif method == "label_propagation":
            node_labels = self.label_propagation()
            groups: Dict[int, List[NodeID]] = defaultdict(list)
            for node, label in node_labels.items():
                groups[label].append(node)
            return dict(groups)
        else:
            raise ValueError(f"Unknown method: {method}")

    def modularity(self, communities: Dict[int, List[NodeID]]) -> float:
        node_to_community: Dict[NodeID, int] = {}
        for comm_id, members in communities.items():
            for node in members:
                node_to_community[node] = comm_id

        m = self._graph.edge_count
        if m == 0:
            return 0.0

        degrees = {node: self._graph.get_degree(node) for node in self._graph.nodes}
        q = 0.0

        for node in self._graph.nodes:
            ci = node_to_community.get(node)
            if ci is None:
                continue
            for neighbor in self._graph.get_neighbors(node):
                cj = node_to_community.get(neighbor)
                if cj is None:
                    continue
                if ci == cj:
                    q += 1.0 - (degrees[node] * degrees[neighbor]) / (2.0 * m)

        q /= (2.0 * m)
        return q

    def community_sizes(self, communities: Dict[int, List[NodeID]]) -> Dict[int, int]:
        return {cid: len(members) for cid, members in communities.items()}

    def giant_component_fraction(self) -> float:
        if self._graph.node_count == 0:
            return 0.0
        comps = self.connected_components()
        if not comps:
            return 0.0
        largest = max(len(members) for members in comps.values())
        return largest / self._graph.node_count

    def num_connected_components(self) -> int:
        comps = self.connected_components()
        return len(comps)

